{"file_path":"src/values.js","content":"/**
 * Value model shared by the parser and the printers.
 *
 * Scalars are tagged objects so that an integer stays distinguishable from a
 * float even when the float happens to hold a whole number.
 */

export class ParseError extends Error {
  constructor(line, reason) {
    super(`line ${line}: ${reason}`)
    this.line = line
    this.reason = reason
  }
}

export class Table {
  constructor() {
    this.map = new Map()
    // true once a [name] header has made this table current
    this.explicit = false
  }
}

export class ArrayValue {
  constructor(isTables) {
    this.items = []
    this.isTables = isTables === true
  }
}

export const str = (v) => ({ kind: 'string', value: v })
export const bool = (v) => ({ kind: 'boolean', value: v })
export const int = (v) => ({ kind: 'integer', value: v })
export const float = (v) => ({ kind: 'float', value: v })

/** Ascending order by Unicode code point (not by UTF-16 code unit). */
export function compareCodePoints(a, b) {
  const x = Array.from(a)
  const y = Array.from(b)
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) {
    const ca = x[i].codePointAt(0)
    const cb = y[i].codePointAt(0)
    if (ca !== cb) return ca < cb ? -1 : 1
  }
  return x.length === y.length ? 0 : x.length < y.length ? -1 : 1
}

export function sortedKeys(table) {
  return Array.from(table.map.keys()).sort(compareCodePoints)
}

export function joinPath(prefix, name) {
  return prefix ? `${prefix}.${name}` : name
}
"}

