{"file_path":"src/parser.js","content":"/**
 * A line oriented configuration parser. Every directive fits on one line, so
 * each line gets its own scanner and its own line number for error reporting.
 */

import {
  ParseError,
  Table,
  ArrayValue,
  str,
  bool,
  int,
  float,
  joinPath,
} from './values.js'

const DIGITS = '[0-9]+(?:_[0-9]+)*'
const INT_RE = new RegExp(`^[+-]?${DIGITS}$`)
const FLOAT_RE = new RegExp(
  `^[+-]?${DIGITS}(?:\\.${DIGITS}(?:[eE][+-]?${DIGITS})?|[eE][+-]?${DIGITS})$`,
)
const BARE_CHAR = /[A-Za-z0-9_-]/

class Scanner {
  constructor(text, line) {
    this.s = text
    this.i = 0
    this.line = line
  }

  get eof() {
    return this.i >= this.s.length
  }

  peek() {
    return this.i < this.s.length ? this.s[this.i] : null
  }

  skipSpace() {
    while (!this.eof && (this.s[this.i] === ' ' || this.s[this.i] === '\t')) this.i++
  }

  /** End of the meaningful part of the line: nothing left, or a comment. */
  done() {
    if (this.eof) return true
    const c = this.s[this.i]
    return c === '#' || c === ';'
  }

  fail(reason) {
    return new ParseError(this.line, reason)
  }
}

// ---------------------------------------------------------------- names ----

function parseBasicString(sc) {
  sc.i++ // opening quote
  let out = ''
  for (;;) {
    if (sc.eof) throw sc.fail('unterminated string')
    const c = sc.s[sc.i]
    if (c === '"') {
      sc.i++
      return out
    }
    if (c !== '\\') {
      out += c
      sc.i++
      continue
    }
    if (sc.i + 1 >= sc.s.length) throw sc.fail('unterminated string')
    const e = sc.s[sc.i + 1]
    if (e === '"' || e === '\\') {
      out += e
      sc.i += 2
    } else if (e === 'n') {
      out += '\n'
      sc.i += 2
    } else if (e === 't') {
      out += '\t'
      sc.i += 2
    } else if (e === 'r') {
      out += '\r'
      sc.i += 2
    } else if (e === '0') {
      out += '\0'
      sc.i += 2
    } else if (e === 'u') {
      const hex = sc.s.slice(sc.i + 2, sc.i + 6)
      if (!/^[0-9A-Fa-f]{4}$/.test(hex)) throw sc.fail('invalid escape \\u')
      out += String.fromCharCode(parseInt(hex, 16))
      sc.i += 6
    } else {
      throw sc.fail(`invalid escape \\${e}`)
    }
  }
}

function parseLiteralString(sc) {
  sc.i++ // opening quote
  const start = sc.i
  while (!sc.eof && sc.s[sc.i] !== "'") sc.i++
  if (sc.eof) throw sc.fail('unterminated string')
  const out = sc.s.slice(start, sc.i)
  sc.i++
  return out
}

function parseName(sc) {
  const c = sc.peek()
  if (c === '"') return parseBasicString(sc)
  if (c === "'") return parseLiteralString(sc)
  const start = sc.i
  while (!sc.eof && BARE_CHAR.test(sc.s[sc.i])) sc.i++
  if (sc.i === start) throw sc.fail('expected a name')
  return sc.s.slice(start, sc.i)
}

/** Names joined by dots, with spaces and tabs allowed around each dot. */
function parseDottedName(sc) {
  sc.skipSpace()
  const names = [parseName(sc)]
  for (;;) {
    const save = sc.i
    sc.skipSpace()
    if (sc.peek() !== '.') {
      sc.i = save
      return names
    }
    sc.i++
    sc.skipSpace()
    names.push(parseName(sc))
  }
}

// --------------------------------------------------------------- values ----

function parseValue(sc, path) {
  sc.skipSpace()
  if (sc.done()) throw sc.fail('expected a value')
  const c = sc.peek()
  if (c === ',' || c === ']' || c === '}') throw sc.fail('expected a value')
  if (c === '"') return str(parseBasicString(sc))
  if (c === "'") return str(parseLiteralString(sc))
  if (c === '[') return parseArray(sc, path)
  if (c === '{') return parseInlineTable(sc, path)

  // A bare word runs up to whitespace or a structural delimiter; a '#' or ';'
  // the value runs into belongs to its text, which then fails to parse.
  const start = sc.i
  while (!sc.eof) {
    const ch = sc.s[sc.i]
    if (ch === ' ' || ch === '\t' || ch === ',' || ch === ']' || ch === '}') break
    sc.i++
  }
  const text = sc.s.slice(start, sc.i)
  if (text === 'true') return bool(true)
  if (text === 'false') return bool(false)
  if (INT_RE.test(text)) return int(Number(text.replace(/_/g, '')))
  if (FLOAT_RE.test(text)) return float(Number(text.replace(/_/g, '')))
  throw sc.fail(`invalid value ${text}`)
}

function parseArray(sc, path) {
  sc.i++ // [
  const arr = new ArrayValue(false)
  for (;;) {
    sc.skipSpace()
    if (sc.done()) throw sc.fail('unterminated array')
    if (sc.peek() === ']') {
      sc.i++
      return arr
    }
    arr.items.push(parseValue(sc, `${path}[${arr.items.length}]`))
    sc.skipSpace()
    if (sc.done()) throw sc.fail('unterminated array')
    const c = sc.peek()
    if (c === ',') {
      sc.i++
      continue
    }
    if (c === ']') {
      sc.i++
      return arr
    }
    throw sc.fail('unterminated array')
  }
}

function parseInlineTable(sc, path) {
  sc.i++ // {
  const table = new Table()
  sc.skipSpace()
  if (sc.done()) throw sc.fail('unterminated inline table')
  if (sc.peek() === '}') {
    sc.i++
    return table
  }
  for (;;) {
    sc.skipSpace()
    if (sc.done()) throw sc.fail('unterminated inline table')
    const names = parseDottedName(sc)
    sc.skipSpace()
    if (sc.peek() !== '=') throw sc.fail('expected = in an inline table')
    sc.i++
    const spot = descend(table, names, path, sc)
    const value = parseValue(sc, spot.path)
    if (spot.table.map.has(spot.key)) {
      throw sc.fail(`key ${spot.path} is defined twice`)
    }
    spot.table.map.set(spot.key, value)
    sc.skipSpace()
    if (sc.done()) throw sc.fail('unterminated inline table')
    const c = sc.peek()
    if (c === ',') {
      sc.i++
      continue
    }
    if (c === '}') {
      sc.i++
      return table
    }
    throw sc.fail('unterminated inline table')
  }
}

// ------------------------------------------------------------ traversal ----

/**
 * Walk the dots of an assignment, creating the tables on the way, and return
 * the table that receives the final name along with its path from the root.
 */
function descend(table, names, prefix, sc) {
  let current = table
  let path = prefix
  for (let i = 0; i < names.length - 1; i++) {
    const name = names[i]
    path = joinPath(path, name)
    let existing = current.map.get(name)
    if (existing === undefined) {
      const fresh = new Table()
      current.map.set(name, fresh)
      current = fresh
      continue
    }
    if (existing instanceof ArrayValue && existing.isTables && existing.items.length > 0) {
      existing = existing.items[existing.items.length - 1]
    }
    if (!(existing instanceof Table)) throw sc.fail(`${path} is not a table`)
    current = existing
  }
  const key = names[names.length - 1]
  return { table: current, key, path: joinPath(path, key) }
}

// --------------------------------------------------------------- parser ----

export function parse(lines) {
  const root = new Table()
  let current = root
  let currentPath = ''

  for (let n = 0; n < lines.length; n++) {
    const sc = new Scanner(lines[n], n + 1)
    sc.skipSpace()
    if (sc.done()) continue // blank line, or a line that is only a comment

    if (sc.peek() === '[') {
      const header = readHeader(sc)
      if (header.isArray) {
        const spot = walkHeader(root, header.names, sc, 'array')
        let existing = spot.table.map.get(spot.key)
        if (existing === undefined) {
          existing = new ArrayValue(true)
          spot.table.map.set(spot.key, existing)
        } else if (!(existing instanceof ArrayValue) || !existing.isTables) {
          throw sc.fail(`${spot.path} is not an array of tables`)
        }
        const fresh = new Table()
        fresh.explicit = true
        existing.items.push(fresh)
        current = fresh
        currentPath = `${spot.path}[${existing.items.length - 1}]`
      } else {
        const spot = walkHeader(root, header.names, sc, 'table')
        const existing = spot.table.map.get(spot.key)
        if (existing === undefined) {
          const fresh = new Table()
          fresh.explicit = true
          spot.table.map.set(spot.key, fresh)
          current = fresh
        } else if (existing instanceof Table) {
          if (existing.explicit) throw sc.fail(`table ${spot.path} is defined twice`)
          existing.explicit = true
          current = existing
        } else {
          throw sc.fail(`${spot.path} is not a table`)
        }
        currentPath = spot.path
      }
      continue
    }

    // <dotted name> = <value>
    const names = parseDottedName(sc)
    sc.skipSpace()
    if (sc.peek() !== '=') throw sc.fail('expected key = value')
    sc.i++
    const spot = descend(current, names, currentPath, sc)
    const value = parseValue(sc, spot.path)
    sc.skipSpace()
    if (!sc.done()) throw sc.fail('trailing text after a value')
    if (spot.table.map.has(spot.key)) {
      throw sc.fail(`key ${spot.path} is defined twice`)
    }
    spot.table.map.set(spot.key, value)
  }

  return root
}

function readHeader(sc) {
  sc.i++ // [
  let isArray = false
  if (sc.peek() === '[') {
    isArray = true
    sc.i++
  }
  const names = parseDottedName(sc)
  sc.skipSpace()
  if (sc.peek() !== ']') throw sc.fail('unterminated table header')
  sc.i++
  if (isArray) {
    if (sc.peek() !== ']') throw sc.fail('unterminated table header')
    sc.i++
  }
  sc.skipSpace()
  if (!sc.done()) throw sc.fail('trailing text after a table header')
  return { names, isArray }
}

/** Walk the leading names of a header, creating the tables on the way. */
function walkHeader(root, names, sc) {
  let current = root
  let path = ''
  for (let i = 0; i < names.length - 1; i++) {
    const name = names[i]
    path = joinPath(path, name)
    let existing = current.map.get(name)
    if (existing === undefined) {
      const fresh = new Table()
      current.map.set(name, fresh)
      current = fresh
      continue
    }
    if (existing instanceof ArrayValue && existing.isTables && existing.items.length > 0) {
      existing = existing.items[existing.items.length - 1]
    }
    if (!(existing instanceof Table)) throw sc.fail(`${path} is not a table`)
    current = existing
  }
  const key = names[names.length - 1]
  return { table: current, key, path: joinPath(path, key) }
}
"}

