    if (sc.peek() === '[') {
      const header = readHeader(sc)
      if (header.isArray) {
        const spot = walkHeader(root, header.names, sc, 'array')
        let existing = spot.table.map.get(spot.key)
        if (existing === undefined) {
          existing = new ArrayValue(true)
          spot.table.map.set(spot.key, existing)
        } else if (!(existing instanceof ArrayValue) || !existing.isTables) {
          throw sc.fail(`${spot.path} is not an array of tables`)
        }
        const fresh = new Table()
        fresh.explicit = true
        existing.items.push(fresh)
        current = fresh
        currentPath = `${spot.path}[${existing.items.length - 1}]`
      } else {
        const spot = walkHeader(root, header.names, sc, 'table')
        const existing = spot.table.map.get(spot.key)
        if (existing === undefined) {
          const fresh = new Table()
          fresh.explicit = true
          spot.table.map.set(spot.key, fresh)
          current = fresh
        } else if (existing instanceof Table) {
          if (existing.explicit) throw sc.fail(`table ${spot.path} is defined twice`)
          existing.explicit = true
          current = existing
        } else {
          throw sc.fail(`${spot.path} is not a table`)
        }
        currentPath = spot.path
      }
      continue
    }

    // <dotted name> = <value>
    const names = parseDottedName(sc)
    sc.skipSpace()
    if (sc.peek() !== '=') throw sc.fail('expected key = value')
    sc.i++
    const spot = descend(current, names, currentPath, sc)
    const value = parseValue(sc, spot.path)
    sc.skipSpace()
    if (!sc.done()) throw sc.fail('trailing text after a value')
    if (spot.table.map.has(spot.key)) {
      throw sc.fail(`key ${spot.path} is defined twice`)
    }
    spot.table.map.set(spot.key, value)
  }

  return root
}

function readHeader(sc) {
  sc.i++ // [
  let isArray = false
  if (sc.peek() === '[') {
    isArray = true
    sc.i++
  }
  const names = parseDottedName(sc)
  sc.skipSpace()
  if (sc.peek() !== ']') throw sc.fail('unterminated table header')
  sc.i++
  if (isArray) {
    if (sc.peek() !== ']') throw sc.fail('unterminated table header')
    sc.i++
  }
  sc.skipSpace()
  if (!sc.done()) throw sc.fail('trailing text after a table header')
  return { names, isArray }
}

/** Walk the leading names of a header, creating the tables on the way. */
function walkHeader(root, names, sc) {
  let current = root
  let path = ''
  for (let i = 0; i < names.length - 1; i++) {
    const name = names[i]
    path = joinPath(path, name)
    let existing = current.map.get(name)
    if (existing === undefined) {
      const fresh = new Table()
      current.map.set(name, fresh)
      current = fresh
      continue
    }
    if (existing instanceof ArrayValue && existing.isTables && existing.items.length > 0) {
      existing = existing.items[existing.items.length - 1]
    }
    if (!(existing instanceof Table)) throw sc.fail(`${path} is not a table`)
    current = existing
  }
  const key = names[names.length - 1]
  return { table: current, key, path: joinPath(path, key) }
}
"}

