import { Table, ArrayValue, sortedKeys } from './values.js'

export function toJson(root) {
  return render(root, '') + '\n'
}

function render(node, indent) {
  const inner = indent + '  '
  if (node instanceof Table) {
    const keys = sortedKeys(node)
    if (keys.length === 0) return '{}'
    const members = keys.map(
      (key) => `${inner}${JSON.stringify(key)}: ${render(node.map.get(key), inner)}`,
    )
    return `{\n${members.join(',\n')}\n${indent}}`
  }
  if (node instanceof ArrayValue) {
    if (node.items.length === 0) return '[]'
    const items = node.items.map((item) => inner + render(item, inner))
    return `[\n${items.join(',\n')}\n${indent}]`
  }
  if (node.kind === 'string') return JSON.stringify(node.value)
  if (node.kind === 'boolean') return node.value ? 'true' : 'false'
  return JSON.stringify(node.value)
}

export function toKeys(root) {
  const lines = []
  for (const key of sortedKeys(root)) emit(root.map.get(key), key, lines)
  return lines.map((line) => line + '\n').join('')
}

function emit(node, path, lines) {
  if (node instanceof Table) {
    lines.push(`${path} table`)
    for (const key of sortedKeys(node)) emit(node.map.get(key), `${path}.${key}`, lines)
    return
  }
  if (node instanceof ArrayValue) {
    lines.push(`${path} array`)
    node.items.forEach((item, i) => emit(item, `${path}[${i}]`, lines))
    return
  }
  lines.push(`${path} ${node.kind}`)
}
"}

