{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * Reads a configuration document from standard input and prints it either as
 * JSON or as a flat listing of the paths it holds.
 */

import { readFileSync } from 'node:fs'
import { ParseError } from './values.js'
import { parse } from './parser.js'
import { toJson, toKeys } from './print.js'

function main(argv) {
  if (argv.length !== 1 || (argv[0] !== 'json' && argv[0] !== 'keys')) {
    process.stderr.write('error: usage: cli.js json|keys\n')
    return 2
  }
  const mode = argv[0]

  let input = ''
  try {
    input = readFileSync(0, 'utf8')
  } catch {
    input = ''
  }

  // Split on newlines, dropping the empty tail a trailing newline leaves.
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  let output
  try {
    const root = parse(lines)
    output = mode === 'json' ? toJson(root) : toKeys(root)
  } catch (error) {
    if (error instanceof ParseError) {
      process.stderr.write(`error: ${error.message}\n`)
      return 2
    }
    throw error
  }

  process.stdout.write(output)
  return 0
}

process.exitCode = main(process.argv.slice(2))
"}

