#!/usr/bin/env node
/**
 * TOML parser and formatter
 * Supports two modes: json (output as JSON) and keys (output as path and type)
 */

import { readFileSync } from 'node:fs';

// ============ ERROR CLASS ============

class ParseError extends Error {
  constructor(lineNum, reason) {
    super(`error: line ${lineNum}: ${reason}`);
  }
}

// ============ PARSER CLASS ============

class TomlParser {
  constructor(lines) {
    this.lines = lines;
    this.root = {};
    this.current = this.root;
    this.currentPath = [];
    this.definedTables = new Set();
  }

  parse() {
    for (let i = 0; i < this.lines.length; i++) {
      const lineNum = i + 1;
      const line = this.lines[i];

      // Skip comments and blank lines
      const trimmed = this.getCommentStart(line);
      if (trimmed.length === 0) {
        continue;
      }

      // Check for header
      if (trimmed[0] === '[') {
        this.parseHeader(trimmed, lineNum);
      } else {
        // Parse key-value pair
        this.parseKeyValue(trimmed, lineNum);
      }
    }

    return this.root;
  }

  // Find where a comment starts (# or ; outside quoted strings)
  getCommentStart(line) {
    let result = '';
    let inSingleQuote = false;
    let inDoubleQuote = false;
    let escape = false;

    for (let i = 0; i < line.length; i++) {
      const char = line[i];

      if (escape) {
        result += char;
        escape = false;
        continue;
      }

      if (inDoubleQuote) {
        result += char;
        if (char === '\\') {
          escape = true;
        } else if (char === '"') {
          inDoubleQuote = false;
        }
        continue;
      }

      if (inSingleQuote) {
        result += char;
        if (char === "'") {
          inSingleQuote = false;
        }
        continue;
      }

      if (char === '"') {
        result += char;
        inDoubleQuote = true;
      } else if (char === "'") {
        result += char;
        inSingleQuote = true;
      } else if (char === '#' || char === ';') {
        break;
      } else {
        result += char;
      }
    }

    return result.trimEnd();
  }

  parseHeader(line, lineNum) {
    if (line[0] !== '[') {
      throw new ParseError(lineNum, 'expected a name');
    }

    // Check for array of tables [[...]]
    if (line[1] === '[') {
      if (!line.endsWith(']]')) {
        throw new ParseError(lineNum, 'unterminated table header');
      }
      const content = line.slice(2, -2).trim();
      this.parseArrayOfTablesHeader(content, lineNum);
    } else {
      if (!line.endsWith(']')) {
        throw new ParseError(lineNum, 'unterminated table header');
      }
      const content = line.slice(1, -1).trim();

      // Check for trailing text
      const afterBracket = line.slice(content.length + 2);
      if (afterBracket.trim().length > 0 && !this.isComment(afterBracket)) {
        throw new ParseError(lineNum, 'trailing text after a table header');
      }

      this.parseTableHeader(content, lineNum);
    }
  }

  isComment(text) {
    const trimmed = text.trim();
    return trimmed.length === 0 || trimmed[0] === '#' || trimmed[0] === ';';
  }

  parseTableHeader(content, lineNum) {
    const names = this.parseDottedName(content, lineNum);

    // Navigate/create the path
    let current = this.root;
    let path = [];

    for (let i = 0; i < names.length; i++) {
      const name = names[i];
      path.push(name);
      const pathStr = path.join('.');

      if (!(name in current)) {
        current[name] = {};
      } else {
        const existing = current[name];
        // Check if it's a table or something else
        if (typeof existing !== 'object' || existing === null || Array.isArray(existing)) {
          throw new ParseError(lineNum, `${pathStr} is not a table`);
        }
      }

      current = current[name];
    }

    // Check if this table was already explicitly defined
    const pathStr = path.join('.');
    if (this.definedTables.has(pathStr)) {
      throw new ParseError(lineNum, `table ${pathStr} is defined twice`);
    }
    this.definedTables.add(pathStr);

    this.current = current;
    this.currentPath = path;
  }

  parseArrayOfTablesHeader(content, lineNum) {
    const names = this.parseDottedName(content, lineNum);

    // Navigate/create the path, except for the last name which should be an array
    let current = this.root;
    let path = [];

    for (let i = 0; i < names.length - 1; i++) {
      const name = names[i];
      path.push(name);
      const pathStr = path.join('.');

      if (!(name in current)) {
        current[name] = {};
      } else {
        const existing = current[name];
        if (typeof existing !== 'object' || existing === null || Array.isArray(existing)) {
          throw new ParseError(lineNum, `${pathStr} is not a table`);
        }
      }

      current = current[name];
    }

    const arrayName = names[names.length - 1];
    path.push(arrayName);
    const pathStr = path.join('.');

    if (!(arrayName in current)) {
      current[arrayName] = [];
    } else {
      const existing = current[arrayName];
      if (!Array.isArray(existing)) {
        throw new ParseError(lineNum, `${pathStr} is not an array of tables`);
      }
    }

    // Append a new table
    const newTable = {};
    current[arrayName].push(newTable);

    this.current = newTable;
    this.currentPath = path;
  }

  parseDottedName(content, lineNum) {
    const names = [];
    const parts = content.split('.');

    for (const part of parts) {
      const trimmed = part.trim();
      if (trimmed.length === 0) {
        throw new ParseError(lineNum, 'expected a name');
      }
      const name = this.parseName(trimmed, lineNum);
      names.push(name);
    }

    return names;
  }

  parseName(text, lineNum) {
    if (text[0] === '"') {
      // Basic string
      if (!text.endsWith('"') || text.length < 2) {
        throw new ParseError(lineNum, 'unterminated string');
      }
      return this.unescapeBasicString(text.slice(1, -1), lineNum);
    } else if (text[0] === "'") {
      // Literal string
      if (!text.endsWith("'") || text.length < 2) {
        throw new ParseError(lineNum, 'unterminated string');
      }
      return text.slice(1, -1);
    } else {
      // Bare word
      const match = text.match(/^[A-Za-z0-9_-]+$/);
      if (!match) {
        throw new ParseError(lineNum, 'expected a name');
      }
      return text;
    }
  }

  parseKeyValue(line, lineNum) {
    // Find the = sign
    const eqIndex = line.indexOf('=');
    if (eqIndex === -1) {
      throw new ParseError(lineNum, 'expected key = value');
    }

    const keyPart = line.slice(0, eqIndex).trim();
    const valuePart = line.slice(eqIndex + 1).trim();

    if (keyPart.length === 0) {
      throw new ParseError(lineNum, 'expected a name');
    }

    if (valuePart.length === 0) {
      throw new ParseError(lineNum, 'expected a value');
    }

    const names = this.parseDottedName(keyPart, lineNum);
    const value = this.parseValue(valuePart, lineNum);

    // Navigate/create the path
    let current = this.current;
    let path = [...this.currentPath];

    for (let i = 0; i < names.length - 1; i++) {
      const name = names[i];
      path.push(name);
      const pathStr = path.join('.');

      if (!(name in current)) {
        current[name] = {};
      } else {
        const existing = current[name];
        if (typeof existing !== 'object' || existing === null || Array.isArray(existing)) {
          throw new ParseError(lineNum, `${pathStr} is not a table`);
        }
      }

      current = current[name];
    }

    const finalName = names[names.length - 1];
    path.push(finalName);
    const pathStr = path.join('.');

    if (finalName in current) {
      throw new ParseError(lineNum, `key ${pathStr} is defined twice`);
    }

    current[finalName] = value;
  }

  parseValue(text, lineNum) {
    // Try to parse as different value types

    // Booleans
    if (text === 'true') {
      return true;
    }
    if (text === 'false') {
      return false;
    }

    // Array
    if (text[0] === '[') {
      return this.parseArray(text, lineNum);
    }

    // Inline table
    if (text[0] === '{') {
      return this.parseInlineTable(text, lineNum);
    }

    // String
    if (text[0] === '"') {
      return this.parseBasicString(text, lineNum);
    }
    if (text[0] === "'") {
      return this.parseLiteralString(text, lineNum);
    }

    // Number or invalid value
    // Try to parse as number
    const numberResult = this.tryParseNumber(text);
    if (numberResult !== null) {
      return numberResult.value;
    }

    throw new ParseError(lineNum, `invalid value ${text}`);
  }

  parseBasicString(text, lineNum) {
    if (!text.endsWith('"') || text.length < 2) {
      throw new ParseError(lineNum, 'unterminated string');
    }
    return this.unescapeBasicString(text.slice(1, -1), lineNum);
  }

  parseLiteralString(text, lineNum) {
    if (!text.endsWith("'") || text.length < 2) {
      throw new ParseError(lineNum, 'unterminated string');
    }
    return text.slice(1, -1);
  }

  unescapeBasicString(text, lineNum) {
    let result = '';
    let i = 0;
    while (i < text.length) {
      if (text[i] === '\\') {
        if (i + 1 >= text.length) {
          throw new ParseError(lineNum, `invalid escape \\`);
        }
        const next = text[i + 1];
        switch (next) {
          case '"':
            result += '"';
            i += 2;
            break;
          case '\\':
            result += '\\';
            i += 2;
            break;
          case 'n':
            result += '\n';
            i += 2;
            break;
          case 't':
            result += '\t';
            i += 2;
            break;
          case 'r':
            result += '\r';
            i += 2;
            break;
          case '0':
            result += '\0';
            i += 2;
            break;
          case 'u':
            if (i + 5 >= text.length) {
              throw new ParseError(lineNum, `invalid escape \\u`);
            }
            const hex = text.slice(i + 2, i + 6);
            if (!/^[0-9a-fA-F]{4}$/.test(hex)) {
              throw new ParseError(lineNum, `invalid escape \\u${hex}`);
            }
            result += String.fromCharCode(parseInt(hex, 16));
            i += 6;
            break;
          default:
            throw new ParseError(lineNum, `invalid escape \\${next}`);
        }
      } else {
        result += text[i];
        i++;
      }
    }
    return result;
  }

  tryParseNumber(text) {
    // Try integer first
    const intMatch = text.match(/^[+-]?\d+(_?\d+)*$/);
    if (intMatch) {
      const numStr = text.replace(/_/g, '');
      return { value: parseInt(numStr, 10), isFloat: false };
    }

    // Try float
    const floatMatch = text.match(/^[+-]?(\d+(_?\d+)*\.(\d+(_?\d+)*)|\d+(_?\d+)*[eE][+-]?\d+(_?\d+)*)$/);
    if (floatMatch) {
      const numStr = text.replace(/_/g, '');
      return { value: parseFloat(numStr), isFloat: true };
    }

    return null;
  }

  parseArray(text, lineNum) {
    if (!text.endsWith(']')) {
      throw new ParseError(lineNum, 'unterminated array');
    }

    const content = text.slice(1, -1).trim();
    if (content.length === 0) {
      return [];
    }

    const items = [];
    let current = '';
    let depth = 0;
    let inSingleQuote = false;
    let inDoubleQuote = false;
    let escape = false;

    for (let i = 0; i < content.length; i++) {
      const char = content[i];

      if (escape) {
        current += char;
        escape = false;
        continue;
      }

      if (inDoubleQuote) {
        current += char;
        if (char === '\\') {
          escape = true;
        } else if (char === '"') {
          inDoubleQuote = false;
        }
        continue;
      }

      if (inSingleQuote) {
        current += char;
        if (char === "'") {
          inSingleQuote = false;
        }
        continue;
      }

      if (char === '"') {
        current += char;
        inDoubleQuote = true;
      } else if (char === "'") {
        current += char;
        inSingleQuote = true;
      } else if (char === '[' || char === '{') {
        current += char;
        depth++;
      } else if (char === ']' || char === '}') {
        current += char;
        depth--;
      } else if (char === ',' && depth === 0) {
        const trimmed = current.trim();
        if (trimmed.length === 0) {
          throw new ParseError(lineNum, 'expected a value');
        }
        items.push(this.parseValue(trimmed, lineNum));
        current = '';
      } else if (char === '#' || char === ';') {
        if (depth === 0) {
          break; // Comment in array
        }
        current += char;
      } else {
        current += char;
      }
    }

    const final = current.trim();
    if (final.length > 0) {
      items.push(this.parseValue(final, lineNum));
    }

    return items;
  }

  parseInlineTable(text, lineNum) {
    if (!text.endsWith('}')) {
      throw new ParseError(lineNum, 'unterminated inline table');
    }

    const content = text.slice(1, -1).trim();
    const table = {};

    if (content.length === 0) {
      return table;
    }

    const pairs = [];
    let current = '';
    let depth = 0;
    let inSingleQuote = false;
    let inDoubleQuote = false;
    let escape = false;

    for (let i = 0; i < content.length; i++) {
      const char = content[i];

      if (escape) {
        current += char;
        escape = false;
        continue;
      }

      if (inDoubleQuote) {
        current += char;
        if (char === '\\') {
          escape = true;
        } else if (char === '"') {
          inDoubleQuote = false;
        }
        continue;
      }

      if (inSingleQuote) {
        current += char;
        if (char === "'") {
          inSingleQuote = false;
        }
        continue;
      }

      if (char === '"') {
        current += char;
        inDoubleQuote = true;
      } else if (char === "'") {
        current += char;
        inSingleQuote = true;
      } else if (char === '[' || char === '{') {
        current += char;
        depth++;
      } else if (char === ']' || char === '}') {
        current += char;
        depth--;
      } else if (char === ',' && depth === 0) {
        const trimmed = current.trim();
        if (trimmed.length > 0) {
          pairs.push(trimmed);
        }
        current = '';
      } else {
        current += char;
      }
    }

    const final = current.trim();
    if (final.length > 0) {
      pairs.push(final);
    }

    for (const pair of pairs) {
      const eqIndex = pair.indexOf('=');
      if (eqIndex === -1) {
        throw new ParseError(lineNum, 'expected = in an inline table');
      }

      const keyPart = pair.slice(0, eqIndex).trim();
      const valuePart = pair.slice(eqIndex + 1).trim();

      if (keyPart.length === 0 || valuePart.length === 0) {
        throw new ParseError(lineNum, 'expected = in an inline table');
      }

      const key = this.parseName(keyPart, lineNum);
      const value = this.parseValue(valuePart, lineNum);

      if (key in table) {
        throw new ParseError(lineNum, `key ${key} is defined twice`);
      }

      table[key] = value;
    }

    return table;
  }
}

// ============ MAIN ============

// Parse command line arguments
const args = process.argv.slice(2);
if (args.length !== 1 || !['json', 'keys'].includes(args[0])) {
  process.stderr.write('error: usage: cli.js json|keys\n');
  process.exit(2);
}

const mode = args[0];

// Read from stdin
let input = '';
try {
  input = readFileSync(0, 'utf8');
} catch (e) {
  process.stderr.write('error: failed to read stdin\n');
  process.exit(2);
}

// Split on newlines and drop empty tail from trailing newline
const lines = input.split('\n');
if (lines.length > 0 && lines[lines.length - 1] === '') {
  lines.pop();
}

try {
  const parser = new TomlParser(lines);
  const document = parser.parse();

  if (mode === 'json') {
    const json = toJSON(document);
    process.stdout.write(json + '\n');
  } else {
    const keys = toKeys(document);
    keys.forEach(line => process.stdout.write(line + '\n'));
  }
  process.exit(0);
} catch (error) {
  if (error instanceof ParseError) {
    process.stderr.write(error.message + '\n');
  } else {
    process.stderr.write('error: ' + error.message + '\n');
  }
  process.exit(2);
}

// ============ JSON OUTPUT ============

function toJSON(obj) {
  return stringifyWithSortedKeys(obj, 0);
}

function stringifyWithSortedKeys(obj, indent) {
  const indentStr = ' '.repeat(indent);
  const nextIndentStr = ' '.repeat(indent + 2);

  if (obj === null) {
    return 'null';
  }

  if (typeof obj === 'boolean') {
    return obj ? 'true' : 'false';
  }

  if (typeof obj === 'number') {
    return String(obj);
  }

  if (typeof obj === 'string') {
    return JSON.stringify(obj);
  }

  if (Array.isArray(obj)) {
    if (obj.length === 0) {
      return '[]';
    }
    const items = obj.map(item => nextIndentStr + stringifyWithSortedKeys(item, indent + 2));
    return '[\n' + items.join(',\n') + '\n' + indentStr + ']';
  }

  if (typeof obj === 'object') {
    const keys = Object.keys(obj).sort((a, b) => {
      return a < b ? -1 : a > b ? 1 : 0;
    });

    if (keys.length === 0) {
      return '{}';
    }

    const pairs = keys.map(key => {
      const value = stringifyWithSortedKeys(obj[key], indent + 2);
      return nextIndentStr + JSON.stringify(key) + ': ' + value;
    });

    return '{\n' + pairs.join(',\n') + '\n' + indentStr + '}';
  }

  return 'undefined';
}

// ============ KEYS OUTPUT ============

function toKeys(obj) {
  const lines = [];
  walkKeys(obj, '', lines);
  return lines;
}

function walkKeys(obj, path, lines) {
  if (Array.isArray(obj)) {
    lines.push(path + ' array');
    for (let i = 0; i < obj.length; i++) {
      const itemPath = path + '[' + i + ']';
      const item = obj[i];
      if (typeof item === 'object' && item !== null) {
        walkKeys(item, itemPath, lines);
      } else {
        const type = typeof item === 'boolean' ? 'boolean' : 
                     typeof item === 'number' ? (Number.isInteger(item) ? 'integer' : 'float') :
                     typeof item === 'string' ? 'string' : 'unknown';
        lines.push(itemPath + ' ' + type);
      }
    }
  } else if (typeof obj === 'object' && obj !== null) {
    // It's a table
    const keys = Object.keys(obj).sort((a, b) => {
      // Sort by code point
      return a < b ? -1 : a > b ? 1 : 0;
    });

    // First emit the table itself if path is not empty
    if (path.length > 0) {
      lines.push(path + ' table');
    }

    for (const key of keys) {
      const value = obj[key];
      const itemPath = path.length > 0 ? path + '.' + key : key;

      if (typeof value === 'object' && value !== null) {
        walkKeys(value, itemPath, lines);
      } else {
        const type = typeof value === 'boolean' ? 'boolean' :
                     typeof value === 'number' ? (Number.isInteger(value) ? 'integer' : 'float') :
                     typeof value === 'string' ? 'string' : 'unknown';
        lines.push(itemPath + ' ' + type);
      }
    }
  }
}

